@CrossOrigin
@RestController
@RequestMapping("/NotebookQuery")
public class NotebookQueryRestController extends BaseSpringRestController {
	
	public NotebookQueryRestController( NotebookService service ) {
        this.service = service;
    }
    
    /**
     * Handles loading a Notebook using a UUID
     * @param		UUID notebookId
     * @return		Notebook
     */    
    @GetMapping("/load")
    public Notebook load( @RequestParam(required=true) UUID notebookId ) {
    	Notebook entity = null;

    	try {  
    		entity = service.getNotebook( new NotebookFetchOneSummary( notebookId ) );
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING, "failed to load Notebook using Id " + notebookId );
            return null;
        }

        return entity;
    }

    /**
     * Handles loading all Notebook business objects
     * @return		Set<Notebook>
     */
    @GetMapping("/")
    public List<Notebook> loadAll() {                
    	List<Notebook> notebookList = null;
        
    	try {
            // load the Notebook
            notebookList = service.getAllNotebook();
            
            if ( notebookList != null )
                LOGGER.log( Level.INFO,  "successfully loaded all Notebooks" );
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING,  "failed to load all Notebooks ", exc );
        	return null;
        }

        return notebookList;
                            
    }



//************************************************************************    
// Attributes
//************************************************************************
    protected Notebook notebook = null;
    protected NotebookService service = null;
    private static final Logger LOGGER = Logger.getLogger(NotebookQueryRestController.class.getName());
    
}
